"""
    Return the string HTML representation of the color
    in 'rgb(red, blue, green)' format.

    :param red:   0 <= int <= 255
    :param green: 0 <= int <= 255
    :param blue:  0 <= int <= 255

    :return: str
    """
def rgb(red: Any, green: Any, blue: Any) -> object {
    assert isinstance(red, int);
    assert (0 <= red < 256);
    assert isinstance(green, int);
    assert (0 <= green < 256);
    assert isinstance(blue, int);
    assert (0 <= blue < 256);
    return ('rgba(%d, %d, %d)' % (red, green, blue));
}

"""Return unique elements of ``seq`` in order"""
def _unique(seq: Any) -> object {
    seen = `set();
    seen_add = seen.add;
    return [
        x
        for x in seq
        if not ((x in seen) or seen_add(x))
    ];
}

"""
    Move a tile. This returns a moved copy; the original is unchaged.

    Parameters
    ----------
    tile : tuple
        containing y and x slice objects
    offset : tuple
        translation, given as ``(y, x)``

    Returns
    -------
    tile : tuple
        a copy; the input is unchaged
    """
def translate(tile: Any, offset: Any) -> object {
    (dy, dx) = offset;
    (y, x) = tile;
    new_tile = (
        slice((y.start + dy), (y.stop + dy)),
        slice((x.start + dx), (x.stop + dx))
    );
    return new_tile;
}

"""Apply intersection-over-union overlap between box_a and box_b
    """
def iou(box_a: Any, box_b: Any, norm: Any) -> object {
    xmin_a = min(box_a[0], box_a[2]);
    ymin_a = min(box_a[1], box_a[3]);
    xmax_a = max(box_a[0], box_a[2]);
    ymax_a = max(box_a[1], box_a[3]);
    xmin_b = min(box_b[0], box_b[2]);
    ymin_b = min(box_b[1], box_b[3]);
    xmax_b = max(box_b[0], box_b[2]);
    ymax_b = max(box_b[1], box_b[3]);
    area_a = (
        ((ymax_a - ymin_a) + (norm == False)) * ((xmax_a - xmin_a) + (norm == False))
    );
    area_b = (
        ((ymax_b - ymin_b) + (norm == False)) * ((xmax_b - xmin_b) + (norm == False))
    );
    if ((area_a <= 0) and (area_b <= 0)) {
        return 0.0;
    }
    xa = max(xmin_a, xmin_b);
    ya = max(ymin_a, ymin_b);
    xb = min(xmax_a, xmax_b);
    yb = min(ymax_a, ymax_b);
    inter_area = (
        max(((xb - xa) + (norm == False)), 0.0)
        * max(((yb - ya) + (norm == False)), 0.0)
    );
    iou_ratio = inter_area / ((area_a + area_b) - inter_area);
    return iou_ratio;
}

"""
    Property: AttributeDefinition.AttributeType
    """
def attribute_type_validator(x: Any) -> object {
    valid_types = ["S", "N", "B"];
    if (x not in valid_types) {
        raise ValueError(("AttributeType must be one of: %s" % ", ".join(valid_types)));
    }
    return x;
}

"""
    Get the 32 least significant bits.

    :param x: A number.
    :return: The 32 LSBits of x.
    """
def int_32_lsb(x: int) -> object {
    return int((4294967295 & x));
}

